import json
import os
import zipfile
import tempfile
import io
import base64

# IoT Device Firmware Update Handler
# Receives firmware update packages from IoT devices via MQTT bridge -> Lambda
# Package format: base64-encoded zip containing firmware manifest and binaries

FIRMWARE_EXTRACT_DIR = '/tmp/firmware_staging'
DEVICE_REGISTRY = '/tmp/device_registry'

def validate_device_id(device_id):
    """Basic device ID format validation"""
    if not device_id or len(device_id) > 64:
        return False
    allowed = set('abcdefghijklmnopqrstuvwxyz0123456789-_')
    return all(c in allowed for c in device_id)

def validate_manifest(manifest_data):
    """Validate firmware manifest structure"""
    required_fields = ['version', 'device_type', 'checksum']
    try:
        manifest = json.loads(manifest_data)
        return all(f in manifest for f in required_fields)
    except (json.JSONDecodeError, TypeError):
        return False

def extract_firmware_package(zip_bytes, device_id):
    """Extract firmware update package to staging directory"""
    extract_path = os.path.join(FIRMWARE_EXTRACT_DIR, device_id)
    os.makedirs(extract_path, exist_ok=True)

    zip_buffer = io.BytesIO(zip_bytes)

    with zipfile.ZipFile(zip_buffer, 'r') as zf:
        # Check total uncompressed size to prevent zip bombs
        total_size = sum(info.file_size for info in zf.infolist())
        if total_size > 50 * 1024 * 1024:  # 50MB limit
            raise ValueError("Firmware package exceeds size limit")

        # Check number of entries
        if len(zf.infolist()) > 100:
            raise ValueError("Too many files in firmware package")

        for zip_info in zf.infolist():
            # Skip directories
            if zip_info.is_dir():
                continue

            # Construct output path
            output_path = os.path.join(extract_path, zip_info.filename)

            # Create parent directories if needed
            os.makedirs(os.path.dirname(output_path), exist_ok=True)

            # Extract file
            with zf.open(zip_info) as src, open(output_path, 'wb') as dst:
                dst.write(src.read())

    return extract_path

def process_firmware_manifest(extract_path):
    """Read and validate the firmware manifest"""
    manifest_path = os.path.join(extract_path, 'manifest.json')
    if not os.path.exists(manifest_path):
        raise ValueError("Missing firmware manifest")

    with open(manifest_path, 'r') as f:
        manifest_data = f.read()

    if not validate_manifest(manifest_data):
        raise ValueError("Invalid firmware manifest")

    return json.loads(manifest_data)

def handler(event, context):
    """Lambda handler for IoT firmware update messages"""
    try:
        # Parse request body
        if event.get('isBase64Encoded'):
            body = json.loads(base64.b64decode(event['body']))
        else:
            body = json.loads(event.get('body', '{}'))

        device_id = body.get('device_id', '')
        firmware_package_b64 = body.get('firmware_package', '')

        # Validate device ID
        if not validate_device_id(device_id):
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Invalid device ID format'})
            }

        # Decode firmware package
        try:
            zip_bytes = base64.b64decode(firmware_package_b64)
        except Exception:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Invalid firmware package encoding'})
            }

        # Extract and process
        extract_path = extract_firmware_package(zip_bytes, device_id)
        manifest = process_firmware_manifest(extract_path)

        return {
            'statusCode': 200,
            'body': json.dumps({
                'status': 'accepted',
                'device_id': device_id,
                'firmware_version': manifest.get('version')
            })
        }

    except ValueError as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': str(e)})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal processing error'})
        }
